import json
from typing import Protocol

class Exporter(Protocol):
    name: str
    def export(self, daten: list[dict]) -> str:
        ...

class CsvExporter:
    name = "csv"
    def export(self, daten):
        return "\n".join(
            f"{d['name']};{d['note']}"
            for d in daten)

class JsonExporter:
    name = "json"
    def export(self, daten):
        return json.dumps(daten)

plugins: dict[str, Exporter] = {}

def registriere(p: Exporter):
    plugins[p.name] = p

registriere(CsvExporter())
registriere(JsonExporter())

daten = [{"name": "Lena", "note": 1}]
for name, p in plugins.items():
    print(name, "->", p.export(daten))
# csv -> Lena;1
# json -> [{"name": "Lena", "note": 1}]

